Code Snippet:
// Server Component
export default function Page() {
  return <ClientButton onClick={() => console.log("clicked")} />;
}

Correct Answer:
A normal server closure cannot cross the client prop boundary. Put this client-only interaction in the client module.

// ClientButton.jsx
"use client";
export default function ClientButton() {
  return <button onClick={() => console.log("clicked")}>Click</button>;
}

// Server page: remove the ordinary function prop.
return <ClientButton />;

Code Snippet:
import dynamic from "next/dynamic";
const Chart = dynamic(() => import("./Chart"), { ssr: false });

export default function Page() {
  return <Chart />;
}

Correct Answer:
ssr: false belongs in a Client Component module. Move the dynamic loading boundary there.

// ClientChart.jsx
"use client";
import dynamic from "next/dynamic";
const Chart = dynamic(() => import("./Chart"), { ssr: false });
export default function ClientChart() {
  return <Chart />;
}

// app/page.jsx (separate file)
import ClientChart from "./ClientChart";
export default function Page() {
  return <ClientChart />;
}
